SELECT U."IdUsuario",U."IdEmpresa","FechaVigencia",S."IdEntidadSSO",SSO."RedirectURL",U."IdEstado",U."CodigoUsuario",U."IdEntidad",U."CodigoMenu",EMP."IdEmpleado",CLI."IdCliente" FROM "BSCL.Plataforma.BD::ACC.Sesion" S INNER JOIN "BSCL.Plataforma.BD::ACC.Usuario" U on U."IdUsuario" = S."IdUsuario" LEFT JOIN "BSCL.Plataforma.BD::ACC.ConfiguracionSSO" SSO on SSO."IdEntidad" = S."IdEntidadSSO" LEFT JOIN "BSCL.SocioNegocio.BD::EMP.Empleado" EMP ON U."TipoEntidad" = 'EMP' AND U."IdEntidad" = EMP."IdEmpleado" LEFT JOIN "BSCL.SocioNegocio.BD::CLI.Cliente" CLI ON U."TipoEntidad" = 'CLI' AND U."IdEntidad" = CLI."IdCliente" WHERE "IdTokenSesion" = :IdTokenSesion AND "TokenValido" = 'S'